footer='''<footer><div class="footer-top"><a class="wordmark dark" href="/"><svg viewBox="0 0 40 40" aria-hidden="true"><path d="M10 30C4 12 19 5 33 7C36 23 25 33 10 30ZM10 30L27 13"/></svg><span>leicester<span class="wordmark-sub">gardening services</span></span></a><a class="underlink" href="/booking">Plan a visit ↗</a></div><nav class="footer-links" aria-label="Footer navigation"><a href="/services">Services</a><a href="/pricing">Pricing</a><a href="/about">About</a><a href="/contact">Contact</a><a href="/privacy">Privacy</a><a href="/proposal">Client proposal</a><a href="/admin">Owner workspace ↗</a></nav><div class="design-disclosure"><div><span class="section-index">A LOOK AT WHAT’S POSSIBLE</span><p>{{publicNotice}} This preview has been prepared by Kamil for discussion with the business; no affiliation or endorsement is implied.</p></div><div><span class="section-index">DISCUSS THIS WEBSITE</span><p>Like what you see? <a class="underlink" href="mailto:mkamil5656@gmail.com?subject=Leicester%20gardening%20website">Email Kamil ↗</a> or <a href="/proposal">explore the proposal</a>.</p></div></div><div class="footer-bottom"><span>Leicester Garden Studio · 2026</span><span>Business service information sourced from the <a href="https://www.leicestergardeningservices.co.uk/" rel="noopener" target="_blank">official website</a>. Prices and availability require owner approval.</span></div></footer>'''
def hero(title,eyebrow,desc,img='hero'):
 return f'''<section class="inner-hero"><img src="/assets/garden-{img}-v2.jpg" alt="Generated garden visual study, not a completed company project."><div class="hero-shade"></div><div class="inner-hero-content"><p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p>{desc}</p></div></section>'''
def section(index,title,text,extra=''):
 return f'''<section class="section-pad editorial"><div class="section-index reveal"><span class="tiny-dot"></span>{index}</div><div class="reveal"><h2>{title}</h2>{text}{extra}</div></section>'''
def cta():return '''<section class="compact-cta section-pad reveal"><div><span class="section-index">A LITTLE PLANNING GOES A LONG WAY</span><h2>Show us your space.<br><i>We’ll take it from there.</i></h2></div><a class="dark-button" href="/booking">Request a visit <span>↗</span></a></section>'''
def card(title,desc,price,url,image='hero'):
 return f'''<a class="service-card" href="{url}"><div class="image-mask"><img src="/assets/garden-{image}-v2.jpg" alt="Generated garden inspiration" loading="lazy"></div><span class="eyebrow">GARDEN & GROUNDS CARE</span><h3>{title}<span>↗</span></h3><p>{desc}</p><span class="price-label">{price}</span></a>'''
pages={}
home=re.search(r'<main id="main">(.*?)</main>',old,re.S).group(1)
home=home.replace('src="assets/','src="/assets/').replace('href="#services"','href="/services"').replace('href="#contact"','href="/booking"').replace('https://www.leicestergardeningservices.co.uk/contact/','/booking')
home=home.replace('Leicester Gardening Services is a family company offering regular commercial maintenance and one-off care for larger gardens and landscapes.','{{intro}}')
home=home.replace('For gardening enquiries, visit<br>the business’s official contact page.','Choose your preferred visit window<br>and share photos of your grounds.').replace('Contact the gardening team','Request a garden visit')
