home=home.replace('The team reviews','The team reviews')
home=home.replace('</h3><div class="service-body" id="service-regular">','</h3><div class="service-body" id="service-regular"><p class="price-label">{{regularPrice}}</p>')
home=home.replace('<div class="service-body" id="service-oneoff" hidden>','<div class="service-body" id="service-oneoff" hidden><p class="price-label">{{oneoffPrice}}</p>')
home=home.replace('<div class="service-body" id="service-lawn" hidden>','<div class="service-body" id="service-lawn" hidden><p class="price-label">{{lawnPrice}}</p>')
pages['/']={'title':'Naturally well kept.','description':'Thoughtful garden and commercial grounds care in Leicester. Explore services and request a visit with garden photos.','body':home,'social':'home'}
cards='<div class="cards-grid">'+card('Regular maintenance','{{regularDescription}}','{{regularPrice}}','/services/regular-maintenance','detail')+card('One-off garden care','{{oneoffDescription}}','{{oneoffPrice}}','/services/one-off-care')+card('Lawn treatment','{{lawnDescription}}','{{lawnPrice}}','/services/lawn-treatment','detail')+'</div>'
pages['/services']={'title':'Every space. Its own kind of care.','description':'Explore regular maintenance, one-off garden care and lawn treatment in Leicester.','body':hero('Every space.<br><i>Its own kind of care.</i>','THE SERVICES','From consistent grounds maintenance to focused one-off attention.')+f'<section class="section-pad">{cards}</section>'+cta(),'social':'services'}
data=[('regular-maintenance','regular','Regular maintenance.','Keep the care<br><i>consistent.</i>','For commercial grounds that need steady, seasonal attention.','Grass cutting|Hedge cutting|Leaf clearance|Border care','A plan for your grounds.','Tell us about the site, access and the jobs you need help with. A regular maintenance scope should reflect the grounds, the season and your priorities.','detail'),('one-off-care','oneoff','One-off garden care.','A fresh start.<br><i>A little breathing room.</i>','Focused attention when your grounds need a reset.','Hedge reductions|Soft landscaping|Site-specific maintenance','Start with the space.','Share a few wide-angle photos and the areas that need attention. Include access points and anything that will help the team understand the work before travelling.','hero'),('lawn-treatment','lawn','Lawn treatment.','A greener outlook.<br><i>From the ground up.</i>','Discuss additional lawn treatment for your garden or commercial grounds.','Lawn treatment|Site requirements discussed|A scope agreed directly','Let the lawn lead.','Photos help show the condition of your lawn. Tell us about the size, your main concern and how the space is used, so the team can discuss appropriate care.','detail')]
